# WARNING: Under review - generated by LLM.

"""Receipt-backed model-visible compaction with verified re-expansion.

Compaction never deletes canonical evidence.  A large tool result stays in
the durable receipt store byte-for-byte; only its model-visible rendering is
replaced by a compact receipt handle.  Re-expansion is an explicit, verified
observation: the receipt is looked up by its content address, its digest must
match, and the requested byte range is returned from the canonical result.

The durable event trace is never mutated by compaction.  The model sees a
bounded working view; the harness retains evidence and can re-expand any
omitted range on demand.
"""

from __future__ import annotations

from dataclasses import dataclass
from typing import TYPE_CHECKING

from .receipts import ReceiptStore

if TYPE_CHECKING:
    from .session import SessionLog

Message = dict[str, str]


class CompactionError(ValueError):
    """A compaction or re-expansion operation is invalid or unsafe."""


@dataclass(frozen=True)
class CompactionResult:
    """The outcome of one receipt-backed compaction pass."""

    compacted: int
    visible_bytes_before: int
    visible_bytes_after: int
    messages: tuple[Message, ...]

    @property
    def saved_bytes(self) -> int:
        return max(0, self.visible_bytes_before - self.visible_bytes_after)


def _payload_bytes(value: str) -> int:
    return len(value.encode("utf-8"))


def compact_tool_results(
    session: "SessionLog",
    store: ReceiptStore,
    *,
    max_result_bytes: int,
    max_handle_chars: int = 240,
) -> CompactionResult:
    """Replace oversized tool-result renderings with verified receipt handles.

    Every ``tool_result`` event whose content exceeds ``max_result_bytes`` is
    looked up in the receipt store by its tool-call ID.  The model-visible
    copy is replaced by the receipt's compact rendering; the canonical bytes
    stay in the store.  Results without a receipt are left untouched (never
    guessed).  The durable session events themselves are not modified.
    """

    if isinstance(max_result_bytes, bool) or not isinstance(max_result_bytes, int):
        raise CompactionError("max_result_bytes must be an integer")
    if max_result_bytes <= 0:
        raise CompactionError("max_result_bytes must be positive")

    messages: list[Message] = []
    compacted = 0
    visible_before = 0
    visible_after = 0
    for event in session.events:
        if event.type != "tool_result":
            continue
        content = event.data.get("content")
        if not isinstance(content, str):
            continue
        visible_before += _payload_bytes(content)
        if _payload_bytes(content) <= max_result_bytes:
            visible_after += _payload_bytes(content)
            messages.append({"role": "user", "content": f"Tool result:\n{content}"})
            continue
        tool_call_id = event.data.get("tool_call_id")
        receipt = (
            store.by_tool_call(tool_call_id) if isinstance(tool_call_id, str) else None
        )
        if receipt is None:
            visible_after += _payload_bytes(content)
            messages.append({"role": "user", "content": f"Tool result:\n{content}"})
            continue
        rendering = receipt.compact_rendering(max_handle_chars)
        visible_after += _payload_bytes(rendering)
        compacted += 1
        messages.append(
            {"role": "user", "content": f"Tool result (compacted):\n{rendering}"}
        )
    return CompactionResult(
        compacted,
        visible_before,
        visible_after,
        tuple(messages),
    )


def expand_receipt_range(
    store: ReceiptStore,
    receipt_id: str,
    *,
    start: int = 0,
    end: int | None = None,
) -> str:
    """Verify and re-expand a bounded byte range of one receipt's result.

    Re-expansion fails closed on digest or range mismatch; the canonical
    evidence is never altered.
    """

    return store.expand(receipt_id, start=start, end=end)


def reexpand_receipt_message(
    store: ReceiptStore,
    rendering: str,
    *,
    start: int = 0,
    end: int | None = None,
) -> str:
    """Re-expand the receipt referenced by one compact rendering.

    Parses the ``expand via receipt <id>`` handle from a compact rendering
    produced by ``EffectReceipt.compact_rendering`` and returns the verified
    canonical bytes for the requested range.
    """

    marker = "expand via receipt "
    index = rendering.rfind(marker)
    if index < 0:
        raise CompactionError("rendering does not reference a receipt")
    receipt_id = rendering[index + len(marker) :].strip()
    if len(receipt_id) != 64 or any(
        character not in "0123456789abcdef" for character in receipt_id
    ):
        raise CompactionError("rendering references an invalid receipt ID")
    return store.expand(receipt_id, start=start, end=end)
